changeSet.sql:
DO $$
DECLARE r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['dml_utils_owner', 'dml_utils_caller', 'ddl_utils_caller'] LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('CREATE ROLE %I NOLOGIN NOBYPASSRLS NOSUPERUSER NOCREATEDB NOCREATEROLE', r);
        END IF;
    END LOOP;
    EXECUTE format('GRANT CREATE ON DATABASE %I TO dml_utils_owner', current_database());
END $$;

GRANT CREATE ON SCHEMA public TO dml_utils_owner;
GRANT ddl_utils_caller, pgbackground_role TO dml_utils_owner;
GRANT dml_utils_owner TO nexus_admin_dmlutils WITH INHERIT FALSE, SET TRUE;
GRANT dml_utils_caller, pgbackground_role TO nexus_admin_dmlutils WITH INHERIT TRUE, SET TRUE;
CREATE SCHEMA IF NOT EXISTS liquibase AUTHORIZATION dml_utils_owner;
